package io.github.diodeme.ji.cli;

import io.github.diodeme.ji.host.LocalTokenService;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.net.StandardProtocolFamily;
import java.net.UnixDomainSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermission;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;

/** Owner-only local IPC that issues launch tokens without URLs, arguments, or environment values. */
final class LaunchTokenIpc implements AutoCloseable {
    private static final int MAX_RESPONSE_BYTES = 128;
    private final Path socket;
    private final LocalTokenService tokens;
    private final ServerSocketChannel server;
    private final AtomicBoolean closed = new AtomicBoolean();
    private final Thread thread;

    LaunchTokenIpc(Path socket, LocalTokenService tokens) {
        this.socket = socket.toAbsolutePath().normalize();
        this.tokens = java.util.Objects.requireNonNull(tokens, "tokens");
        try {
            Files.createDirectories(this.socket.getParent());
            Files.deleteIfExists(this.socket);
            server = ServerSocketChannel.open(StandardProtocolFamily.UNIX);
            server.bind(UnixDomainSocketAddress.of(this.socket));
            if (Files.getFileStore(this.socket).supportsFileAttributeView("posix")) {
                Files.setPosixFilePermissions(this.socket, Set.of(
                        PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE));
            }
        } catch (IOException | UnsupportedOperationException failure) {
            throw new IllegalStateException("launch-token IPC is unavailable", failure);
        }
        thread = Thread.ofPlatform().name("ji-launch-token-ipc").start(this::serve);
    }

    private void serve() {
        while (!closed.get()) {
            try (SocketChannel client = server.accept()) {
                byte[] response = (tokens.issue() + "\n").getBytes(StandardCharsets.US_ASCII);
                ByteBuffer output = ByteBuffer.wrap(response);
                while (output.hasRemaining()) client.write(output);
            } catch (IOException failure) {
                if (!closed.get()) close();
            }
        }
    }

    static String request(Path socket) {
        try (SocketChannel client = SocketChannel.open(StandardProtocolFamily.UNIX)) {
            client.connect(UnixDomainSocketAddress.of(socket.toAbsolutePath().normalize()));
            var output = new ByteArrayOutputStream();
            ByteBuffer buffer = ByteBuffer.allocate(MAX_RESPONSE_BYTES + 1);
            while (client.read(buffer) >= 0) {
                buffer.flip();
                output.write(buffer.array(), buffer.position(), buffer.remaining());
                buffer.clear();
                if (output.size() > MAX_RESPONSE_BYTES) {
                    throw new IllegalStateException("launch-token IPC response is too large");
                }
            }
            String token = [REDACTED_CREDENTIAL]
            if (!token.matches("[A-Za-z0-9_-]{32,128}")) {
                throw new IllegalStateException("launch-token IPC response is invalid");
            }
            return token;
        } catch (IOException | UnsupportedOperationException failure) {
            throw new IllegalStateException("cannot request launch token", failure);
        }
    }

    @Override
    public void close() {
        if (!closed.compareAndSet(false, true)) return;
        try {
            server.close();
            if (Thread.currentThread() != thread) thread.join(2_000);
            if (thread.isAlive()) throw new IllegalStateException("launch-token IPC did not stop");
            Files.deleteIfExists(socket);
        } catch (IOException failure) {
            throw new IllegalStateException("cannot close launch-token IPC", failure);
        } catch (InterruptedException failure) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("interrupted while closing launch-token IPC", failure);
        }
    }
}
